import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:url_launcher/url_launcher.dart';
class VarnixInfoScreen extends StatelessWidget {
 final String section; const VarnixInfoScreen({super.key,required this.section});
 static const bg=Color(0xFF0F0F1A),card=Color(0xFF211936),purple=Color(0xFFA78BFA);
 Future<List<Map<String,dynamic>>> load() async { final db=Supabase.instance.client; if(section=='updates'){final r=await db.from('app_releases').select().eq('is_published',true).order('published_at',ascending:false).limit(30);return List<Map<String,dynamic>>.from(r);} if(section=='apps'){final r=await db.from('other_apps').select().eq('is_active',true).order('sort_order');return List<Map<String,dynamic>>.from(r);} final r=await db.from('content_documents').select().eq('slug',section).eq('is_published',true).limit(1);return List<Map<String,dynamic>>.from(r);}
 String get title=>switch(section){'about'=>'درباره وارنیکس','terms'=>'شرایط و قوانین','privacy'=>'حریم خصوصی','apps'=>'سایر برنامه‌های ما',_=>'به‌روزرسانی‌ها'};
 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:bg,appBar:AppBar(title:Text(title),backgroundColor:bg),body:FutureBuilder<List<Map<String,dynamic>>>(future:load(),builder:(context,s){
 if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator()); if(s.hasError)return const Center(child:Text('دریافت اطلاعات ممکن نشد. اتصال اینترنت و دیتابیس را بررسی کن.',style:TextStyle(color:Colors.white70))); final rows=s.data??[]; if(rows.isEmpty)return const Center(child:Text('محتوایی برای نمایش وجود ندارد.',style:TextStyle(color:Colors.white70)));
 if(section=='apps')return ListView(padding:const EdgeInsets.all(16),children:rows.map((r)=>Card(color:card,child:ListTile(leading:const CircleAvatar(backgroundColor:purple,child:Icon(Icons.apps,color:Colors.white)),title:Text(r['name']?.toString()??'',style:const TextStyle(color:Colors.white)),subtitle:Text('${r['description']??''}\n${r['status']=='published'?'منتشر شده':'به‌زودی'}',style:const TextStyle(color:Colors.white70)),isThreeLine:true,trailing:r['status']=='published'&&(r['store_url']?.toString().isNotEmpty??false)?IconButton(icon:const Icon(Icons.open_in_new,color:purple),onPressed:()=>launchUrl(Uri.parse(r['store_url'].toString()),mode:LaunchMode.externalApplication)):null))).toList());
 if(section=='updates')return ListView(padding:const EdgeInsets.all(16),children:rows.map((r)=>Card(color:card,child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('نسخه ${r['version']} • ${r['title']}',style:const TextStyle(color:purple,fontWeight:FontWeight.bold,fontSize:17)),const SizedBox(height:10),Text(r['notes']?.toString()??'',style:const TextStyle(color:Colors.white,height:1.8)),if(r['is_mandatory']==true)const Text('این به‌روزرسانی ضروری است.',style:TextStyle(color:Colors.orangeAccent)),if(r['download_url']?.toString().isNotEmpty==true)TextButton.icon(onPressed:()=>launchUrl(Uri.parse(r['download_url'].toString()),mode:LaunchMode.externalApplication),icon:const Icon(Icons.download),label:const Text('دریافت نسخه جدید'))])))).toList());
 final d=rows.first;return ListView(padding:const EdgeInsets.all(20),children:[Text(d['title']?.toString()??title,style:const TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('نسخه ${d['version']??'1.0'} • آخرین ویرایش: ${d['updated_at']??'—'}',style:const TextStyle(color:Colors.white54,fontSize:12)),const Divider(color:Colors.white24,height:28),SelectableText(d['body']?.toString()??'',style:const TextStyle(color:Colors.white,height:1.9,fontSize:15))];
 })));
}
